using UnityEngine;
using UnityEngine.Rendering;
namespace BWVR {
public sealed partial class IslandWeather {
 public bool PlayerLightningTarget(PlayImpactTarget target)=>target!=null&&target.gameObject.activeInHierarchy&&byId.TryGetValue(target.id,out var found)&&found==target&&target.villager==null&&Combustible(target)&&target.GetComponent<ThrowableTree>()?.Uprooted!=true&&target.GetComponent<CarryItem>()?.held!=true&&(season().worldPlay?.Damage(target.id)??0)<1;
}
public sealed partial class WorldBrush {
 public const float LightningCost=20,LightningChargeSeconds=1.2f,LightningCooldown=3;
 PlayImpactTarget chargedTarget;SliceState lightningSeason;float chargeBegan,nextLightning,chargeRadius=4;bool chargeHeld,chargeLocked,readySound;LineRenderer chargeRing;
 public float LightningCharge=>chargeHeld&&chargedTarget!=null?Mathf.Clamp01((Season.Hybrid.time-chargeBegan)/LightningChargeSeconds):0;
 void BuildLightning(){var go=new GameObject("Lightning charge halo");go.transform.SetParent(transform,false);chargeRing=go.AddComponent<LineRenderer>();chargeRing.sharedMaterial=material;chargeRing.positionCount=48;chargeRing.useWorldSpace=false;chargeRing.widthMultiplier=nav.Scale*.25f;chargeRing.shadowCastingMode=ShadowCastingMode.Off;chargeRing.receiveShadows=false;chargeRing.enabled=false;}
 void LightningSeason(){if(lightningSeason==Season)return;CancelLightning();nextLightning=0;lightningSeason=Season;}
 public bool CanLightning(PlayImpactTarget target,out string reason){EnsureSeason();LightningSeason();reason="";if(Season.paused||miracles.Suspended){reason="Paused";return false;}if(!weather.PlayerLightningTarget(target)){reason="Aim at a standing tree or building";return false;}if(Season.Hybrid.time<nextLightning){reason="Lightning is settling";return false;}if(!miracles.CanAfford(LightningCost)){reason="Not enough spiritual energy";return false;}var m=weather.State.Find(target.id);if(m?.burning==true){reason="Already burning";return false;}if(weather.BurningCount>=WeatherState.FireLimit||m==null&&weather.State.materials.Length>=WeatherState.MaterialLimit){reason="The storm is at its limit";return false;}return true;}
 public bool ProcessLightning(PlayImpactTarget target,bool held,float dt){EnsureSeason();LightningSeason();StopRain();StopWind();StopWhirlwind();if(Season.paused||miracles.Suspended||!HybridState.Number(dt,0,1)||dt<=0){CancelLightning();return false;}
  if(held){if(chargeLocked)return false;if(!CanLightning(target,out var reason)){ClearLightningCharge();Reason=reason;return false;}if(!chargeHeld||chargedTarget!=target){chargeHeld=true;chargedTarget=target;chargeBegan=Season.Hybrid.time;readySound=false;var bounds=target.Bounds(nav.Scale);foreach(var r in target.GetComponentsInChildren<MeshRenderer>())if(r.enabled)bounds.Encapsulate(r.bounds);Point=new Vector3(bounds.center.x,bounds.max.y+nav.Scale*2,bounds.center.z);chargeRadius=Mathf.Clamp(Mathf.Max(bounds.extents.x,bounds.extents.z)/nav.Scale*.7f,4,12);IslandAudio.Cue(IslandSound.Notice,target.transform.position,GetEntityId().GetHashCode(),.35f);}if(Season.Hybrid.time-chargeBegan>8){ClearLightningCharge();chargeLocked=true;Reason="Release to charge again";return false;}Active=true;Reason="";DrawLightningCharge();if(LightningCharge>=1&&!readySound){readySound=true;IslandAudio.Cue(IslandSound.Chime,Point,GetEntityId().GetHashCode(),.4f);}return false;}
  bool ready=chargeHeld&&chargedTarget==target&&LightningCharge>=1&&!chargeLocked;ClearLightningCharge();chargeLocked=false;if(!ready){Reason="Hold to charge, then release";return false;}if(!CanLightning(target,out var failed)){Reason=failed;return false;}if(!weather.Strike(target.id)){Reason="Target unavailable";return false;}
  miracles.SpendEnergy(LightningCost);nextLightning=Season.Hybrid.time+LightningCooldown;Pulses++;Point=target.Bounds(nav.Scale).center;Reason="";creature.InvalidateLesson("Player lightning is not creature work");bool burning=weather.State.Find(target.id)?.burning==true;Season.Hybrid.Evidence.Add(Season.Hybrid.time,EvidenceKind.Miracle,EvidenceSource.PlayerMiracle,CreatureAction.IdleOrObserve,target.id,"Player lightning: "+(burning?"ignited":"heated; no ignition")+"; cost "+miracles.EnergyCost(LightningCost));return true;
 }
 void DrawLightningCharge(){chargeRing.enabled=true;chargeRing.transform.position=Point;float p=LightningCharge;chargeRing.positionCount=Mathf.Max(2,Mathf.RoundToInt(48*p));for(int i=0;i<chargeRing.positionCount;i++){float a=i*Mathf.PI*2/47;chargeRing.SetPosition(i,new Vector3(Mathf.Cos(a)*chargeRadius,0,Mathf.Sin(a)*chargeRadius)*nav.Scale);}chargeRing.startColor=chargeRing.endColor=Color.Lerp(new Color(.4f,.7f,1,.6f),Color.white,p);}
 void ClearLightningCharge(){chargeHeld=false;chargedTarget=null;readySound=false;Active=false;if(chargeRing!=null)chargeRing.enabled=false;}
 void CancelLightning(){ClearLightningCharge();chargeLocked=false;}
}
public sealed partial class GodToolPalette {
 PlayImpactTarget lightningAim;
 void AimLightning(Ray ray){lightningAim=null;bool hitSomething=Physics.Raycast(ray,out var hit,8*rig.localScale.x);PreviewPoint=hitSomething?hit.point:ray.GetPoint(2*rig.localScale.x);if(hitSomething)lightningAim=hit.collider.GetComponentInParent<PlayImpactTarget>();PreviewValid=Brush.CanLightning(lightningAim,out var reason);Reason=reason;preview.SetActive(hitSomething);preview.transform.position=PreviewPoint;PreviewShape(PreviewValid,3);previewMaterial.color=PreviewValid?new Color(.5f,.8f,1):new Color(1,.25f,.18f);}
 bool LightningPointer(Ray ray,bool pressed,float dt){AimLightning(ray);bool cast=Brush.ProcessLightning(lightningAim,pressed&&!releaseGate,dt);if(cast){Uses++;feedback?.Invoke(true,"Lightning struck");}hint.text="Lightning · "+(Brush.Active?(Brush.LightningCharge>=1?"Release to strike":"Charging "+Mathf.RoundToInt(Brush.LightningCharge*100)+"%"):PreviewValid?"Hold to charge · release to strike":Reason);return true;}
}
}
